<script setup>
import {Building2,Globe,ArrowUpRight,CreditCard,Receipt,Users,Activity,RefreshCw} from 'lucide-vue-next'
import {ref,onMounted} from 'vue'
import {request} from './client'
import ActionNotice from './ActionNotice.vue'
const emit=defineEmits(['navigate']),data=ref(null),busy=ref(false),error=ref('')
const quickIcons={'Plans':CreditCard,'Billing':Receipt,'Admin access':Users,'Readiness':Activity}
const campusName=site=>site==='sisuacademylk.com'?'SISU Campus':site==='teen.sisuacademylk.com'?'Teen Academy':site
const labels={student_memberships:'Active student memberships',teachers:'Verified teachers',institutes:'Verified institutes',pending_profiles:'Provider reviews pending',pending_payouts:'Payout requests pending'}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await request('owner_operations','overview',{},'GET')}catch(e){error.value=e.message;data.value=null}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<section class="overview"><ActionNotice :message="error" :failure="true"/>
<header><div><h2>Welcome to your workspace</h2><p>Your people, institutes and everyday tasks. All in one place.</p></div><button class="button subtle" :disabled="busy" @click="load"><RefreshCw :size="15" :class="{refreshing:busy}"/> {{busy?'Refreshing…':'Refresh'}}</button></header>
<div v-if="busy&&!data" class="panel" role="status">Loading your platform overview…</div>
<template v-if="data"><div class="overview-stats">
<button class="owner-summary-card" @click="emit('navigate','Organizations')"><span class="owner-summary-heading"><span class="owner-summary-icon"><Building2 :size="24"/></span>Hosted institutes</span><strong>{{data.hosted_institutes}}</strong><small>Manage institutes <span>↗</span></small></button>
<button class="owner-summary-card owner-summary-mint" @click="emit('navigate','Provisioning')"><span class="owner-summary-heading"><span class="owner-summary-icon"><Globe :size="24"/></span>Website setup requests</span><strong>{{data.setup_pending}}</strong><small>{{data.setup_pending?'Review pending setup':'View website setup'}} <span>↗</span></small></button>
</div></template>
<h3 class="section-label">Quick actions</h3><div class="quick-actions"><button v-for="item in [{name:'Plans',title:'Plans & pricing',text:'Update your shared catalogue'},{name:'Billing',title:'Subscriptions',text:'Review invoices and billing'},{name:'Admin access',title:'Owner access',text:'Manage your admin team'},{name:'Readiness',title:'Service health',text:'Check services and email'}]" :key="item.name" @click="emit('navigate',item.name)"><span class="quick-icon"><component :is="quickIcons[item.name]" :size="21"/></span><strong>{{item.title}} <ArrowUpRight :size="16"/></strong><small>{{item.text}}</small></button></div>
<template v-if="data"><h3 class="section-label">Connected campuses</h3><article v-for="campus in data.campuses" :key="campus.site" class="panel campus"><header><div><h3>{{campusName(campus.site)}}</h3><p class="campus-address">{{campus.site}}</p><span class="connection" :class="{unavailable:!campus.available}">{{campus.available?'Reporting available':'Reporting unavailable'}}</span></div><a v-if="campus.available" class="button subtle" :href="campus.url" target="_blank" rel="noopener">Open administration ↗</a></header><p v-if="!campus.available" role="status">{{campus.message}}</p><template v-else><div class="campus-metrics"><div v-for="(value,key) in campus.counts" :key="key"><strong>{{value}}</strong><span>{{labels[key]||key}}</span></div></div><details><summary>About these numbers and campus access</summary><p>Student memberships count campus membership records, not unique people across campuses.</p><p>Manage provider approvals, subscriptions, payouts and signup policies in the campus administration. An authorized owner account is required.</p></details></template></article><p v-if="!data.campuses.length" class="panel">No campus reporting connections configured.</p></template>
</section></template>
<style scoped>
