pus summary{cursor:pointer}.campus details p{margin-top:10px}@media(max-width:1100px){.quick-actions{grid-template-columns:1fr 1fr}}@media(max-width:650px){header{align-items:start;flex-direction:column}.overview-stats{grid-template-columns:1fr}.quick-actions{grid-template-columns:1fr 1fr}.owner-summary-card>strong{font-size:34px}}

</style>
<style scoped>
.overview{font-family:Manrope,Arial,sans-serif}.overview>header{padding:24px 28px;background:linear-gradient(110deg,#eee7fa,#faf8ff);border:1px solid #e7def4;border-radius:18px;margin-bottom:24px}.overview>header h2{font-size:23px;font-weight:700}.overview>header p{font-size:14px;color:#766787}.overview .button{display:inline-flex;align-items:center;gap:8px}.overview .owner-summary-card{display:flex!important;flex-direction:column;align-items:stretch;justify-content:flex-start;gap:0;min-height:224px;margin:0;width:100%;box-shadow:0 4px 18px #35255004;padding:26px 28px}.overview .owner-summary-heading{display:flex;align-items:center;gap:12px;font-size:14px;font-weight:600}.owner-summary-icon{display:inline-flex;padding:11px;background:#f0eafa;color:#7347a2;border-radius:13px}.owner-summary-mint .owner-summary-icon{background:#fff4e5;color:#ba8540}.overview .owner-summary-card.owner-summary-mint{background:white}.overview .owner-summary-card>strong{font-size:48px;line-height:1.15;font-weight:700;margin:22px 0;color:#292039;align-self:flex-start}.overview .owner-summary-card small{font-size:13px;margin-top:auto}.overview .quick-actions button{display:flex!important;flex-direction:column;align-items:stretch;gap:0;margin:0;width:100%;padding:22px;min-height:158px;transition:transform .15s,box-shadow .15s}.overview .quick-actions button:hover{transform:translateY(-2px);box-shadow:0 8px 24px #4530620a}.quick-icon{display:flex;align-items:center;justify-content:center;background:#f2edf9;color:#7347a2;border-radius:11px;width:40px;height:40px;margin-bottom:18px}.overview .quick-actions strong{font-size:14px}.overview .quick-actions small{font-size:12px}.overview .section-label{font-size:17px!important;margin:32px 0 16px}.overview .campus{padding:28px}.overview .campus header{align-items:center}.overview .campus h3{font-size:19px;margin:0 0 4px}.overview .campus-address{font-size:12px;color:#948a9f;margin:0 0 12px}.overview .campus-metrics{gap:12px;padding:20px 0}.overview .campus-metrics>div{background:#f8f8fc;border-radius:12px;padding:18px 16px}.overview .campus-metrics strong{font-size:28px;font-weight:700}.overview .campus-metrics span{font-size:12px;line-height:1.5;display:block}.overview .connection{display:inline-flex;align-items:center;gap:6px;padding:5px 9px}.overview .connection:before{content:'';width:5px;height:5px;background:currentColor;border-radius:50%}.refreshing{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:650px){.overview>header{padding:20px}.overview .quick-actions{grid-template-columns:1fr}.overview .campus{padding:20px}.overview .campus-metrics{grid-template-columns:1fr 1fr}}
</style>
