.overview .owner-summary-card{background:#f1eafa;border:1px solid #e0d2f0;color:#44246b;min-height:210px;padding:25px 28px;box-shadow:none;transition:border-color .15s,box-shadow .15s}
.overview .owner-summary-card.owner-summary-mint{background:#eaf6f1;border-color:#cce5da;color:#205c4d}
